    def prepare_non_staff(self, scenario: RequestScenario) -> None:
        """Authenticate a user excluded by the provider's creation permission resolver."""
        scenario.user = get_user_model().objects.create(
            username="group_non_staff", is_staff=False
        )

    def prepare_alternate_action(self, scenario: RequestScenario) -> None:
        """Register an unrelated action without changing the shared endpoint."""
        action = replace(
            INTERNAL_IM_PROVIDER.creation_actions[0],
            key="example_action",
            handler=f"{__name__}.alternate_creation",
        )
        provider = replace(
            INTERNAL_IM_PROVIDER, key="example", creation_actions=(action,)
        )
        self.enterContext(
            patch.dict(IM_PROVIDER_REGISTRY._registry, {"example": provider})
        )

    def prepare_callable_action(self, scenario: RequestScenario) -> None:
        """Register direct creation and permission functions alongside string-based actions."""
        self.prepare_alternate_action(scenario)
        provider = IM_PROVIDER_REGISTRY.get("example")
        action = replace(
            provider.creation_actions[0],
            handler=alternate_creation,
            permission_resolver=resolve_hook(
                provider.creation_actions[0].permission_resolver
            ),
        )
        self.enterContext(
            patch.dict(
                IM_PROVIDER_REGISTRY._registry,
                {"example": replace(provider, creation_actions=(action,))},
            )
        )

    def prepare_solo_meeting(self, scenario: RequestScenario) -> None:
        """Enable conferencing and request a provider-owned meeting without invitees."""
        self.prepare_call()
        scenario.data = {"provider": "internal", "action": "start_meeting", "client_id": str(uuid4()), "media_mode": "video"}

    def solo_meeting(self, response: HttpResponse) -> bool:
        """Only the initiating account is invited and no conversation is required."""
        session = ConferenceSession.objects.get(pk=response.json()["session_id"])
        return session.room.conversation_id is None and session.participants.count() == 1 and session.participants.get().user_id == self.admin_user.pk
